--
-- Name: v_alarm_records; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_alarm_records AS
 SELECT d.point_code,
    p.field_name,
    to_char(d.ts, 'MM-DD HH24:MI:SS'::text) AS ts,
    round((d.value)::numeric, 2) AS value,
    p.alarm_threshold,
    p.unit,
    d.source
   FROM (public.timeseries_data d
     JOIN public.measurement_point p USING (point_code))
  WHERE ((p.alarm_threshold IS NOT NULL) AND (d.value > p.alarm_threshold));


ALTER VIEW public.v_alarm_records OWNER TO postgres;

--
-- Name: VIEW v_alarm_records; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.v_alarm_records IS '历史超阈明细视图：value > alarm_threshold 的全部记录';


--
-- Name: v_data_quality; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_data_quality AS
 SELECT point_code,
    count(*) AS rows_total,
    to_char(min(ts), 'HH24:MI:SS'::text) AS ts_first,
    to_char(max(ts), 'HH24:MI:SS'::text) AS ts_last,
    sum(
        CASE
            WHEN ((ts - prev_ts) > '00:00:05'::interval) THEN 1
            ELSE 0
        END) AS gaps
   FROM ( SELECT timeseries_data.point_code,
            timeseries_data.ts,
            lag(timeseries_data.ts) OVER (PARTITION BY timeseries_data.point_code ORDER BY timeseries_data.ts) AS prev_ts
           FROM public.timeseries_data) t
  GROUP BY point_code
  ORDER BY point_code;


ALTER VIEW public.v_data_quality OWNER TO postgres;

--
-- Name: VIEW v_data_quality; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.v_data_quality IS '数据质量视图：每测点行数/首末时间/时间断点数（四工况每小时一段，断点=工况间隔，属预期设计）';


--
-- Name: v_fault_episodes; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_fault_episodes AS
 WITH g AS (
         SELECT alarm_event.point_code,
            alarm_event.ts,
            alarm_event.value,
            alarm_event.threshold,
            alarm_event.source,
            (alarm_event.ts - lag(alarm_event.ts) OVER (PARTITION BY alarm_event.point_code ORDER BY alarm_event.ts)) AS gap
           FROM public.alarm_event
        ), ep AS (
         SELECT g.point_code,
            g.ts,
            g.value,
            g.threshold,
            g.source,
            g.gap,
            sum(
                CASE
                    WHEN ((g.gap > '00:00:30'::interval) OR (g.gap IS NULL)) THEN 1
                    ELSE 0
                END) OVER (PARTITION BY g.point_code ORDER BY g.ts) AS ep_id
           FROM g
        )
 SELECT point_code,
    min(ts) AS start_ts,
    max(ts) AS end_ts,
    count(*) AS alarm_points,
    round((max(value))::numeric, 1) AS peak_value,
    threshold,
    max(source) AS source,
    round(EXTRACT(epoch FROM (max(ts) - min(ts))), 1) AS duration_s
   FROM ep
  GROUP BY point_code, ep_id, threshold
  ORDER BY (min(ts));


ALTER VIEW public.v_fault_episodes OWNER TO postgres;

