--
-- Name: v_source_stats; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_source_stats AS
 SELECT d.source,
    count(*) AS rows_total,
    count(DISTINCT d.point_code) AS points,
    to_char(min(d.ts), 'MM-DD HH24:MI'::text) AS ts_min,
    to_char(max(d.ts), 'MM-DD HH24:MI'::text) AS ts_max,
    round((avg(d.value))::numeric, 3) AS avg_value,
    sum(
        CASE
            WHEN (d.value > p.alarm_threshold) THEN 1
            ELSE 0
        END) AS alarm_rows
   FROM (public.timeseries_data d
     JOIN public.measurement_point p USING (point_code))
  GROUP BY d.source
  ORDER BY (min(d.ts));


